//! Shell integration: completions, shell functions such as `wt`, and the zsh
//! config valet owns: `~/.zshenv`, `~/.zshrc` rendered from `shell/rc/`, plus
//! cached init output, all written by [`install`] (`valet hooks install`) as
//! locked generated files.
//!
//! A child process cannot change its parent shell's directory, so `wt` is a
//! shell function: it asks the binary for a path and `cd`s there. `valet` itself
//! is always the binary.

use crate::generated;
use crate::template::{self, Vars};
use anyhow::{Context, Result};
use clap::CommandFactory;
use clap_complete::Shell;
use std::fs;
use std::path::{Path, PathBuf};
use std::time::Duration;

/// The shell templates (`shell/rc/`, `shell/`), embedded; see [`template`].
pub const RC_FILES: &[(&str, &str)] = &[
    (
        "zshenv.zsh.j2",
        include_str!("../../shell/rc/zshenv.zsh.j2"),
    ),
    ("zshrc.zsh.j2", include_str!("../../shell/rc/zshrc.zsh.j2")),
    (
        "zshrc-body.zsh",
        include_str!("../../shell/rc/zshrc-body.zsh"),
    ),
    ("zshenv-dropin.zsh", include_str!("../../shell/zshenv.zsh")),
    ("zshrc-dropin.zsh", include_str!("../../shell/zshrc.zsh")),
    (
        "env-common.sh",
        include_str!("../../shell/rc/env-common.sh"),
    ),
    ("bashrc.sh.j2", include_str!("../../shell/rc/bashrc.sh.j2")),
    (
        "zprofile.zsh.j2",
        include_str!("../../shell/rc/zprofile.zsh.j2"),
    ),
    (
        "zshenv-stub.zsh",
        include_str!("../../shell/rc/zshenv-stub.zsh"),
    ),
];
/// Powerlevel10k config, sourced from the drop-in dir (not a template: its
/// `%D{%H...}` would read as a tag).
pub const P10K: &str = include_str!("../../shell/rc/p10k.zsh");

/// zinit, cloned at a pinned tag and commit
/// (`gh api repos/zdharma-continuum/zinit/git/refs/tags/v3.17.1`).
pub const ZINIT_URL: &str = "https://github.com/zdharma-continuum/zinit";
pub const ZINIT_TAG: &str = "v3.17.1";
pub const ZINIT_COMMIT: &str = "0616639b9577f8708ff664c2b157abfcefc42ffa";

/// Tool init output cached as `<name>.zsh`; `_valet_init <name> <cmd>...` in
/// the templates must name the same command.
const INITS: &[(&str, &[&str])] = &[
    ("zoxide", &["zoxide", "init", "zsh"]),
    ("atuin", &["atuin", "init", "zsh", "--disable-up-arrow"]),
    ("broot", &["broot", "--print-shell-function", "zsh"]),
    ("fzf", &["fzf", "--zsh"]),
];
const INIT_TIMEOUT: Duration = Duration::from_secs(20);
/// Regenerate note for the files [`install`] writes.
fn regen() -> String {
    format!(
        "{} (source: {})",
        generated::cmd("hooks install"),
        generated::source("shell/")
    )
}

#[derive(clap::Args)]
pub struct InitArgs {
    #[arg(value_enum)]
    shell: InitShell,
}

#[derive(clap::ValueEnum, Clone, Copy)]
enum InitShell {
    Zsh,
    Bash,
}

/// zsh only: keep $PWD under ~ when a directory symlink in ~ points elsewhere
/// (~/ws -> /mnt/disk/ws), so prompts show ~/ws/... wherever a tool cd'd to; and a
/// short prompt path (first two parts, last two folders). The links are read
/// at shell start; nothing is hardcoded.
const PROMPT_PWD_ZSH: &str = r#"# valet: show paths through ~'s directory symlinks (~/ws/... not /mnt/disk/ws/...)
typeset -gA _valet_home_links
() {
  local l t
  for l in $HOME/*(N@-/) $HOME/.*(N@-/); do
    t=${l:A}
    [[ $t != $l ]] && _valet_home_links[$t]=$l
  done
}
_valet_logical_pwd() {
  local t
  for t in ${(k)_valet_home_links}; do
    if [[ $PWD == $t || $PWD == $t/* ]]; then
      builtin cd -q -- "${_valet_home_links[$t]}${PWD#$t}"
      return
    fi
  done
}
# Short prompt path: first two parts and last two folders, `..` between
# (~/ws/../Fol1/Fol2); p10k's dir segment shows it.
_valet_short_pwd() {
  local p=${(%):-%~}
  local -a parts=("${(@s:/:)p}")
  (( ${#parts} > 5 )) && p="${parts[1]}/${parts[2]}/../${parts[-2]}/${parts[-1]}"
  typeset -g _valet_dir=$p
}
typeset -g POWERLEVEL9K_DIR_CONTENT_EXPANSION='${_valet_dir}'
autoload -Uz add-zsh-hook
add-zsh-hook chpwd _valet_logical_pwd
add-zsh-hook chpwd _valet_short_pwd
_valet_logical_pwd
_valet_short_pwd
"#;

const WRAPPER: &str = r#"# valet shell integration (generated by `valet shell-init`)
# wt [place|query]: cd to a named place or a picked repo/worktree (a binary cannot cd its parent shell)
wt() {
  local __valet_target
  __valet_target="$(command valet cd "$@")" || return
  [ -n "$__valet_target" ] && builtin cd -- "$__valet_target"
}
# `git clone URL` (no other arguments) clones the valet way: <Userland>/Repos
# layout, listed in config.toml; then cd there. Anything else is plain git.
git() {
  if [ "$1" = clone ] && [ $# -eq 2 ]; then
    local __valet_target
    __valet_target="$(command valet repos clone "$2")" || return
    builtin cd -- "$__valet_target"
  else
    command git "$@"
  fi
}
"#;

pub fn init(args: InitArgs) -> Result<()> {
    let zsh = matches!(args.shell, InitShell::Zsh);
    print!("{}", init_text(zsh, true)?);
    Ok(())
}

/// zsh functions that complete `repos` arguments from live data
/// (`valet repos complete`): aliases, repos, branches.
fn zsh_dynamic_fns() -> String {
    let n = generated::name();
    format!(
        r#"_{n}_repos_target() {{
  local -a c; c=(${{(f)"$(command {n} repos complete target 2>/dev/null)"}})
  _describe -t targets 'alias, repo or branch' c
}}
_{n}_repos_branch() {{
  local w=${{opt_args[-r]:-${{opt_args[--repo]}}}}
  [[ -z $w && $words[1] == path ]] && (( CURRENT == 3 )) && w=$words[2]
  local -a c; c=(${{(f)"$(command {n} repos complete branch ${{w:+$w}} 2>/dev/null)"}})
  _describe -t branches 'branch' c
}}
_{n}_repos_repo() {{
  local -a c; c=(${{(M)${{(f)"$(command {n} repos complete target 2>/dev/null)"}}:#*:repo}})
  _describe -t repos 'repo' c
}}
_{n}_vars_name() {{
  local -a c; c=(${{(f)"$(command {n} vars complete names 2>/dev/null)"}})
  _describe -t names 'value' c
}}
_{n}_vars_group() {{
  local -a c; c=(${{(f)"$(command {n} vars complete groups 2>/dev/null)"}})
  _describe -t groups 'group' c
}}
"#
    )
}

/// Point clap's static `repos` and `vars` argument specs at [`zsh_dynamic_fns`].
fn zsh_dynamic(comp: String) -> String {
    let n = generated::name();
    comp.replace(
        ":repos_target:_default'",
        &format!(":repos_target:_{n}_repos_target'"),
    )
    .replace(
        ":repos_branch:_default'",
        &format!(":repos_branch:_{n}_repos_branch'"),
    )
    .replace(
        "'-r+[]:REPO:_default'",
        &format!("'-r+[]:REPO:_{n}_repos_repo'"),
    )
    .replace(
        "'--repo=[]:REPO:_default'",
        &format!("'--repo=[]:REPO:_{n}_repos_repo'"),
    )
    .replace(
        ":vars_name:_default'",
        &format!(":vars_name:_{n}_vars_name'"),
    )
    .replace(
        ":vars_group:_default'",
        &format!(":vars_group:_{n}_vars_group'"),
    )
}

/// `valet shell-init` output. `completions`: inline the completion function
/// (the cache autoloads `completions/_valet` instead).
fn init_text(zsh: bool, completions: bool) -> Result<String> {
    use std::fmt::Write as _;
    let mut o = String::new();
    o.push_str(WRAPPER);
    if zsh {
        o.push_str(PROMPT_PWD_ZSH);
    }
    for snippet in super::shell_snippets(zsh) {
        let _ = writeln!(o, "{}", snippet.trim_end());
    }
    o.push_str(&super::hooks::shell_snippet(zsh));
    let o = o.replace(
        "__VALET_PR_CACHE__",
        &crate::cmd::pr::cache_dir()?.display().to_string(),
    );
    let mut o = o;
    let shell = if zsh { Shell::Zsh } else { Shell::Bash };
    if !completions {
        return Ok(o);
    }
    // Completions need compinit; skip them quietly in shells without it.
    if zsh {
        o.push_str("if (( $+functions[compdef] )); then\n");
    }
    let mut buf = Vec::new();
    let mut cmd = crate::Cli::command();
    clap_complete::generate(shell, &mut cmd, generated::name(), &mut buf);
    let comp = String::from_utf8(buf)?;
    if zsh {
        o.push_str(&zsh_dynamic_fns());
        o.push_str(&zsh_dynamic(comp));
    } else {
        o.push_str(&comp);
    }
    if zsh {
        o.push_str("fi\n");
    }
    Ok(o)
}

/// Render a template from [`RC_FILES`].
pub fn render(name: &str, vars: &Vars) -> Result<String> {
    Ok(format!(
        "{}\n",
        template::render_files(name, RC_FILES, vars)?
    ))
}

fn home() -> Result<PathBuf> {
    std::env::var_os("HOME")
        .filter(|h| !h.is_empty())
        .map(PathBuf::from)
        .context("HOME is not set")
}

/// zinit's folder (plugins, snippets) in the Zsh app: `Data/Zinit`.
fn zinit_dir() -> Result<PathBuf> {
    Ok(crate::cmd::apps::root()?.join("Applications/Zsh/Data/Zinit"))
}

/// zinit's checkout (rendered into `.zshrc`; cloned by `install_zinit`).
fn zinit_home() -> Result<PathBuf> {
    Ok(zinit_dir()?.join("zinit.git"))
}

/// Template variables of the host drop-ins (`shell/zshenv.zsh`,
/// `shell/zshrc.zsh`) and the home dir's rc files. Every host reads them, so
/// paths are shell text: `${USERLAND}/...`, and `userland_seed`, a spelling
/// that leads to Userland on every host (through the home dir's link),
/// from which each shell computes `$USERLAND`.
pub fn dropin_vars() -> Result<Vars> {
    let root = crate::cmd::apps::root()?;
    Ok(Vars::from([
        ("userland_seed", seed(&root)?),
        (
            "generated",
            crate::cmd::apps::in_shell(&crate::cmd::apps::generated_dir(&root)),
        ),
        ("name", generated::name().to_owned()),
    ]))
}

/// ROOT spelled so that every host reaches it: through a link in the home
/// dir as `${HOME}/<link>/...`, else as it is.
fn seed(root: &Path) -> Result<String> {
    let p = crate::cmd::apps::portable(root);
    Ok(match p.strip_prefix(home()?) {
        Ok(rest) => format!("${{HOME}}/{}", rest.display()),
        Err(_) => p.display().to_string(),
    })
}

/// ZDOTDIR, `<Userland>/Applications/Zsh/Settings`: `.zshenv`, `.zshrc`,
/// `p10k.zsh`, drop-ins (`zshenv.d/`, `zshrc.d/`). The home dir keeps only
/// the `~/.zshenv` stub pointing here.
pub fn zsh_dir() -> Result<PathBuf> {
    Ok(crate::cmd::apps::root()?.join("Applications/Zsh/Settings"))
}

fn cache_dir() -> Result<PathBuf> {
    Ok(crate::cmd::apps::generated_dir(&crate::cmd::apps::root()?))
}

/// Write the zsh config: the `~/.zshenv` stub (sets ZDOTDIR), and in
/// ZDOTDIR `.zshenv`, `.zshrc`, p10k; zinit when missing, and the init
/// caches. Every file is locked. Files of the old layout (`~/.zshrc`,
/// `~/.config/zsh/`) that valet generated are removed.
pub fn install(dry: bool) -> Result<()> {
    use crate::cmd::apps::in_shell;
    let h = home()?;
    let zsh = zsh_dir()?;
    let cache = cache_dir()?;
    // Shell text: every host reads these files. `.zshenv` runs before the
    // drop-in sets $USERLAND, but after the stub sets $ZDOTDIR.
    let vars = Vars::from([
        ("zsh_dir", "${ZDOTDIR}".to_owned()),
        ("shell_cache", in_shell(&cache.join("init"))),
        ("zinit_home", in_shell(&zinit_home()?)),
        ("zinit_dir", in_shell(&zinit_dir()?)),
        (
            "zsh_cache",
            in_shell(&crate::cmd::apps::root()?.join("Applications/Zsh/Caches")),
        ),
    ]);
    let hdr = generated::header("#", &regen());
    let stub = format!("{hdr}{}", render("zshenv-stub.zsh", &dropin_vars()?)?);
    let files = [
        (h.join(".zshenv"), stub),
        (
            zsh.join(".zshenv"),
            format!("{hdr}{}", render("zshenv.zsh.j2", &vars)?),
        ),
        (
            zsh.join(".zshrc"),
            format!("{hdr}{}", render("zshrc.zsh.j2", &vars)?),
        ),
        (zsh.join("p10k.zsh"), format!("{hdr}{P10K}")),
        // bash (Claude Code's shell, scripts) gets zsh's environment.
        (
            h.join(".bashrc"),
            format!("{hdr}{}", render("bashrc.sh.j2", &dropin_vars()?)?),
        ),
        (
            h.join(".bash_profile"),
            format!("{hdr}[ -r ~/.bashrc ] && . ~/.bashrc\n"),
        ),
        (
            h.join(".zprofile"),
            format!("{hdr}{}", render("zprofile.zsh.j2", &dropin_vars()?)?),
        ),
    ];
    // The old layout: generated files in ~ and ~/.config/zsh.
    let old_dir = h.join(".config/zsh");
    let mut old = vec![h.join(".zshrc"), old_dir.join("p10k.zsh")];
    for sub in ["zshenv.d", "zshrc.d"] {
        for e in fs::read_dir(old_dir.join(sub))
            .into_iter()
            .flatten()
            .flatten()
        {
            old.push(e.path());
        }
    }
    for p in old {
        let ours = fs::read_to_string(&p)
            .is_ok_and(|t| t.starts_with("# Generated by ") && t.contains(" hooks install`"));
        if ours {
            println!(
                "{}remove {} (old layout)",
                if dry { "would: " } else { "" },
                p.display()
            );
            if !dry {
                generated::remove(&p)?;
            }
        }
    }
    for (path, body) in &files {
        if fs::read_to_string(path).ok().as_deref() == Some(body) {
            continue;
        }
        println!(
            "{}write {}",
            if dry { "would: " } else { "" },
            path.display()
        );
        if !dry {
            generated::write(path, body)?;
        }
    }
    if dry {
        return Ok(());
    }
    install_zinit()?;
    repair_completion_links(&zinit_dir()?)?;
    write_cache()
}

/// Zinit links each plugin completion into `completions/` by absolute path;
/// after zinit's folder moves, the links dangle and compinit fails when it
/// rebuilds its dump. Point each dangling link at the same file under DIR
/// (the part after `/zinit/`), else remove it.
fn repair_completion_links(dir: &Path) -> Result<()> {
    let mut fixed = 0;
    for e in fs::read_dir(dir.join("completions"))
        .into_iter()
        .flatten()
        .flatten()
    {
        let p = e.path();
        let Ok(target) = fs::read_link(&p) else {
            continue;
        };
        if p.exists() {
            continue;
        }
        let t = target.to_string_lossy();
        let moved = t
            .rsplit_once("/zinit/")
            .map(|(_, rest)| dir.join(rest))
            .filter(|n| n.exists());
        fs::remove_file(&p)?;
        if let Some(n) = moved {
            // Relative: zinit's absolute links name one host's spelling.
            std::os::unix::fs::symlink(
                crate::cmd::apps::relative(&n, &dir.join("completions")),
                &p,
            )?;
        }
        fixed += 1;
    }
    if fixed > 0 {
        println!("repaired {fixed} zinit completion link(s)");
    }
    Ok(())
}

/// Clone zinit at [`ZINIT_COMMIT`] when [`zinit_home`] is
/// missing.
fn install_zinit() -> Result<()> {
    let dir = zinit_home()?;
    if dir.join("zinit.zsh").is_file() {
        return Ok(());
    }
    println!("clone zinit {ZINIT_TAG} into {}", dir.display());
    let t = Duration::from_secs(120);
    crate::proc::Cmd::new("git")
        .args(["clone", "--quiet", "--branch", ZINIT_TAG, ZINIT_URL])
        .arg(&dir)
        .timeout(t)
        .checked()?;
    let head = crate::proc::Cmd::new("git")
        .arg("-C")
        .arg(&dir)
        .args(["rev-parse", "HEAD"])
        .timeout(t)
        .checked()?;
    anyhow::ensure!(
        head.trim() == ZINIT_COMMIT,
        "zinit {ZINIT_TAG} is {head}, expected {ZINIT_COMMIT}"
    );
    Ok(())
}

/// The caches in `Applications/Valet/Data/Generated`: `shell-init.zsh` (+ its
/// `.zwc`), `completions/_valet`, and `init/<tool>.zsh` for each installed tool
/// in [`INITS`]. Also run by `valet upgrade` and `valet hooks enable/disable`,
/// whose state shell-init reflects.
pub fn write_cache() -> Result<()> {
    let dir = cache_dir()?;
    let init = format!(
        "{}{}",
        generated::header("#", &regen()),
        init_text(true, false)?
    );
    let f = dir.join("shell-init.zsh");
    if generated::write(&f, &init)? || !dir.join("shell-init.zsh.zwc").exists() {
        let zwc = dir.join("shell-init.zsh.zwc");
        generated::unlock(&zwc);
        let _ = fs::remove_file(&zwc);
        crate::proc::Cmd::new("zsh")
            .arg("-c")
            .arg("zcompile -R -- \"$1\"")
            .arg("zsh")
            .arg(&f)
            .timeout(INIT_TIMEOUT)
            .checked()
            .context("zcompile shell-init.zsh")?;
        generated::lock(&zwc);
    }
    let mut comp = Vec::new();
    let mut cmd = crate::Cli::command();
    clap_complete::generate(Shell::Zsh, &mut cmd, generated::name(), &mut comp);
    let comp = zsh_dynamic(String::from_utf8(comp)?);
    // `#compdef` must stay the first line for compinit; the header goes second.
    let comp = match comp.split_once('\n') {
        Some((first, rest)) => format!(
            "{first}\n{}{}{rest}",
            generated::header("#", &regen()),
            zsh_dynamic_fns()
        ),
        None => comp,
    };
    generated::write(
        &dir.join("completions")
            .join(format!("_{}", generated::name())),
        &comp,
    )?;
    let root = crate::cmd::apps::root()?;
    for (name, argv) in INITS {
        let f = dir.join("init").join(format!("{name}.zsh"));
        let Some(bin) = crate::proc::which(argv[0]) else {
            generated::remove(&f)?;
            continue;
        };
        let out = crate::proc::Cmd::new(bin)
            .args(&argv[1..])
            .timeout(INIT_TIMEOUT)
            .checked()
            .with_context(|| argv.join(" "))?;
        generated::write(&f, &format!("{}{out}\n", generated::header("#", &regen())))?;
    }
    generated::write(
        &dir.join("gitleaks.toml"),
        &format!(
            "{}{}",
            generated::header("#", &regen()),
            include_str!("../../gitleaks.toml")
        ),
    )?;
    crate::cmd::apps::generated_readme(&root)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn host_rc_renders_paths_and_caches() {
        let vars = Vars::from([
            ("zsh_dir", "/h/.config/zsh".to_owned()),
            ("shell_cache", "/h/G/init".to_owned()),
            ("zinit_home", "/h/Z/zinit.git".to_owned()),
            ("zinit_dir", "/h/Z".to_owned()),
            ("zsh_cache", "/h/C".to_owned()),
        ]);
        let rc = render("zshrc.zsh.j2", &vars).unwrap();
        assert!(rc.contains(r#"local f="/h/G/init/$1.zsh""#));
        assert!(rc.contains(r#""/h/.config/zsh"/zshrc.d/*.zsh(N)"#));
        assert!(!rc.contains("mise activate"), "Userland links commands");
        // Every cached init the rc asks for is one valet writes.
        for line in rc
            .lines()
            .filter(|l| l.trim_start().starts_with("_valet_init "))
        {
            let mut w = line.split_whitespace().skip(1);
            let (name, cmd): (&str, Vec<&str>) = (w.next().unwrap(), w.collect());
            let (_, argv) = INITS.iter().find(|(n, _)| *n == name).expect(line);
            assert_eq!(&cmd, argv, "{line}");
        }
        let env = render("zshenv.zsh.j2", &vars).unwrap();
        assert!(!env.contains("GHQ_ROOT"));
    }

    #[test]
    fn shared_rc_files_compute_userland_per_host() {
        let vars = Vars::from([
            ("userland_seed", "${HOME}/ws/Userland".to_owned()),
            (
                "generated",
                "${USERLAND}/Applications/Valet/Data/Generated".to_owned(),
            ),
            ("name", "valet".to_owned()),
        ]);
        let stub = render("zshenv-stub.zsh", &vars).unwrap();
        assert!(stub.contains("_ul=${${:-${HOME}/ws/Userland}:A}"), "{stub}");
        assert!(stub.contains("export ZDOTDIR=\"$_ul/Applications/Zsh/Settings\""));
        for f in ["zshenv-dropin.zsh", "bashrc.sh.j2"] {
            let t = render(f, &vars).unwrap();
            assert!(
                t.contains("_ul=$(cd \"${HOME}/ws/Userland\" 2>/dev/null && pwd -P)"),
                "{f}: {t}"
            );
            assert!(
                t.contains("export USERLAND=\"${_ul:-${HOME}/ws/Userland}\""),
                "{f}"
            );
            assert!(
                t.contains("XDG_CONFIG_HOME=\"$USERLAND/Library/Preferences\""),
                "{f}"
            );
            assert!(
                t.contains("\"${USERLAND}/Applications/Valet/Data/Generated/environment.sh\""),
                "{f}"
            );
            assert!(!t.contains("USERLAND_LOCAL"), "{f}");
            // USERLAND is set before anything names it.
            assert!(t.find("export USERLAND=") < t.find("$USERLAND/"), "{f}");
        }
    }

    #[test]
    fn dangling_completion_links_follow_zinit() {
        let d = std::env::temp_dir().join(format!("valet-test-{}-zinit", std::process::id()));
        let _ = fs::remove_dir_all(&d);
        let src = d.join("plugins/p/src");
        fs::create_dir_all(&src).unwrap();
        fs::create_dir_all(d.join("completions")).unwrap();
        fs::write(src.join("_a"), "x").unwrap();
        let link = |n: &str, t: &str| {
            std::os::unix::fs::symlink(t, d.join("completions").join(n)).unwrap()
        };
        link("_a", "/old/.local/share/zinit/plugins/p/src/_a");
        link("_gone", "/old/.local/share/zinit/plugins/p/src/_gone");
        repair_completion_links(&d).unwrap();
        assert_eq!(
            fs::read_link(d.join("completions/_a")).unwrap(),
            Path::new("../plugins/p/src/_a")
        );
        assert!(d.join("completions/_a").exists());
        assert!(fs::symlink_metadata(d.join("completions/_gone")).is_err());
        let _ = fs::remove_dir_all(&d);
    }
}
